/** A database-backed work area for the administrative and commercial modules. */
public final class OperationalPane extends VBox {
 private final Database db; private final Runnable onProfileChanged; private final Operations ops; private final SaleRecovery recovery; private final PurchaseRecovery purchaseRecovery; private final java.util.function.BiConsumer<String,UUID> onResolved; private PurchaseRecovery.Pending pendingPurchase; private final List<PurchaseItem> purchaseItems=new ArrayList<>(); private final Security.User user; private final String mode; private final TableView<List<String>> table=new TableView<>(); private CartView cartView; private TableView<PurchaseItem> purchaseDraft; private final Map<Long,String> purchaseNames=new HashMap<>(); private final Label status=new Label(); private final List<CartItem> cart=new ArrayList<>(); private String query; private int page; private ReportGrid currentGrid; private final TextField filter=new TextField(); private final DatePicker from=new DatePicker(LocalDate.now().minusDays(30)),to=new DatePicker(LocalDate.now().plusDays(30)); private UUID pendingKey; private Long pendingClient; private String pendingMethod; private java.math.BigDecimal pendingTotal; private List<CartItem> pendingItems;
 public OperationalPane(Database db,Security.User user,String mode,String title,Runnable onProfileChanged,java.util.function.BiConsumer<String,UUID> onResolved){this.db=db;this.onProfileChanged=onProfileChanged;this.onResolved=onResolved;this.ops=new Operations(db);this.recovery=new SaleRecovery(db);this.purchaseRecovery=new PurchaseRecovery(db);this.user=user;this.mode=mode;this.query=mode;getStyleClass().add("workspace");setSpacing(14);Label heading=new Label(title);heading.getStyleClass().add("heading");getChildren().add(heading);table.setId("operationalTable");table.setPlaceholder(new Label("Sin registros."));table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_ALL_COLUMNS);VBox.setVgrow(table,Priority.ALWAYS);
  FlowPane actions=new FlowPane();actions.setHgap(8);actions.setVgap(8);Button refresh=button("Actualizar",this::refresh);actions.getChildren().add(refresh);
  switch(mode){
   case "suppliers","customers" -> {if(admin()){actions.getChildren().addAll(button("Nuevo",()->contact(false)),button("Editar",()->contact(true)));}}
   case "users" -> {if(admin())actions.getChildren().addAll(button("Nuevo usuario",()->account(false)),button("Editar usuario",()->account(true)));}
   case "batches" -> {if(admin())actions.getChildren().addAll(button("Ajustar",this::adjust),button("Bloquear / habilitar",this::block));}
   case "sales" -> {Button view=button("Ver comprobante",this::receipt);MenuButton more=new MenuButton("Más acciones");MenuItem print=new MenuItem("Imprimir comprobante");print.setOnAction(e->printReceipt());more.getItems().add(print);if(admin()){MenuItem cancel=new MenuItem("Anular venta");cancel.setOnAction(e->voidSale());more.getItems().add(cancel);}view.disableProperty().bind(table.getSelectionModel().selectedItemProperty().isNull());more.disableProperty().bind(table.getSelectionModel().selectedItemProperty().isNull());actions.getChildren().addAll(view,more);}
   case "pending" -> {actions.getChildren().addAll(button("Resolver venta",this::resolvePending),button("Cancelar solicitud",this::cancelPending));}
   case "purchase_pending" -> {if(admin())actions.getChildren().addAll(button("Resolver compra",this::resolvePurchase),button("Cancelar solicitud",this::cancelPurchase));}
   case "purchases" -> {if(admin()){Button add=button("Agregar producto",this::purchaseAdd);add.setId("purchaseAdd");Button commit=button("Registrar compra",this::purchaseCommit);commit.setId("purchaseCommit");actions.getChildren().addAll(add,commit,button("Vaciar borrador",this::clearPurchase));}}
   case "settings" -> {if(admin())actions.getChildren().addAll(button("Datos de la farmacia",()->ProfileDialog.open(getScene().getWindow(),db,user,()->{onProfileChanged.run();refresh();})),button("Serie interna (prueba)",this::internalSeries),button("Crear respaldo",this::backup),button("Modificar parámetro",this::setting));}
   case "reports" -> {ComboBox<String> choices=new ComboBox<>();choices.getItems().addAll("Existencias","Productos más vendidos","Ventas","Compras","Vencimientos","Movimientos","Resumen de IVA","Comprobantes internos","Anulaciones internas");if(admin())choices.getItems().addAll("Actividad administrativa","Conciliación de datos");choices.setValue("Existencias");query="stock";choices.setOnAction(e->{page=0;query=switch(choices.getValue()){case "Productos más vendidos"->"top";case "Resumen de IVA"->"tax_summary";case "Comprobantes internos"->"internal_docs";case "Anulaciones internas"->"voided_docs";case "Ventas"->"sales";case "Compras"->"purchases";case "Vencimientos"->"batches";case "Movimientos"->"movements";case "Actividad administrativa"->"audit";case "Conciliación de datos"->"reconciliation";default->"stock";};refresh();});actions.getChildren().addAll(choices,new Label("Desde"),from,new Label("Hasta"),to,button("Exportar página CSV",this::export),button("Exportar reporte completo",this::exportAll));}
   case "cart" -> {query="stock";Button add=button("Agregar producto",this::cartAdd);add.setId("cartAdd");Button checkout=button("Confirmar venta",this::checkout);checkout.setId("cartCheckout");actions.getChildren().addAll(add,checkout,button("Vaciar carrito",this::clearCart));}
  }
  filter.setPromptText("Filtrar filas visibles");filter.setPrefWidth(190);filter.textProperty().addListener((o,a,b)->filterRows());actions.getChildren().add(filter);if(!Set.of("cart","pending","purchase_pending").contains(mode)){Button prev=button("Anterior",()->{if(page>0){page--;refresh();}}),next=button("Siguiente",()->{if(currentGrid!=null&&currentGrid.rows().size()==100){page++;refresh();}});actions.getChildren().addAll(prev,next);}
  if(mode.equals("cart")){setOnKeyPressed(e->{if(e.isControlDown()&&e.getCode()==javafx.scene.input.KeyCode.ENTER){checkout();e.consume();}else if(e.getCode()==javafx.scene.input.KeyCode.F2){cartAdd();e.consume();}});Label shortcuts=new Label("F2 agregar · Ctrl+Enter confirmar");shortcuts.getStyleClass().add("muted");getChildren().add(shortcuts);}getChildren().addAll(actions,table);if(mode.equals("purchases")&&admin())addPurchaseDraft();if(mode.equals("cart")){cartView=new CartView(cart,()->currentGrid,()->pendingKey!=null);getChildren().add(cartView);}getChildren().add(status);refresh();
 }
 private boolean admin(){return user.role().equals("ADMIN");}
 private Button button(String label,Runnable action){Button b=new Button(label);b.setOnAction(e->action.run());return b;}
 private <T>void run(Callable<T> job,java.util.function.Consumer<T> success){setDisable(true);status.setText("Procesando…");Task<T> task=new Task<>(){protected T call()throws Exception{return job.call();}};task.setOnSucceeded(e->{setDisable(false);status.setText("Actualizado");success.accept(task.getValue());});task.setOnFailed(e->{setDisable(false);Throwable ex=task.getException();status.setText(pendingKey==null?"No se completó la operación":"Resultado incierto: reintente la misma venta");error(ex);});Thread t=new Thread(task);t.setDaemon(true);t.start();}
 public void reload(){if(!isDisabled())refresh();}
 private void refresh(){String q=query;LocalDate start=from.getValue(),end=to.getValue();run(()->mode.equals("pending")?pendingGrid():mode.equals("purchase_pending")?purchasePendingGrid():mode.equals("reports")?ops.reportPage(q,start,end,page*100,100):mode.equals("cart")?ops.grid(q):ops.page(q,page*100,100),this::display);}
 private ReportGrid pendingGrid()throws Exception {List<List<String>> rows=new ArrayList<>();for(var p:recovery.list(user))rows.add(List.of(p.id().toString(),p.customer()==null?"":p.customer().toString(),p.method(),p.total().toPlainString(),Integer.toString(p.items().size())));return new ReportGrid(List.of("Solicitud","Cliente","Pago","Total","Líneas"),rows);}
 private void resolvePending(){try{UUID id=UUID.fromString(selected().get(0));run(()->recovery.resolve(user,id),r->{info("Venta #"+r.id()+" registrada. Total: "+r.total());run(()->{recovery.acknowledge(user,id,false);return null;},x->{onResolved.accept("sale",id);refresh();});});}catch(Exception ex){error(ex);}}
 private void cancelPending(){try{UUID id=UUID.fromString(selected().get(0));Alert a=new Alert(Alert.AlertType.CONFIRMATION,"¿Cancelar esta solicitud pendiente? Una venta ya registrada no se cancelará.",ButtonType.OK,ButtonType.CANCEL);if(a.showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK)run(()->{recovery.acknowledge(user,id,true);return null;},x->{onResolved.accept("sale",id);refresh();});}catch(Exception ex){error(ex);}}
 private ReportGrid purchasePendingGrid()throws Exception{List<List<String>> rows=new ArrayList<>();for(var p:purchaseRecovery.list(user))rows.add(List.of(p.id().toString(),p.supplier()==null?"Sin proveedor":p.supplier().toString(),Integer.toString(p.items().size())));return new ReportGrid(List.of("Solicitud","Proveedor","Líneas"),rows);}
 private void resolvePurchase(){try{UUID id=UUID.fromString(selected().get(0));run(()->purchaseRecovery.resolve(user,id),number->{info("Compra #"+number+" registrada.");run(()->{purchaseRecovery.acknowledge(user,id,false);return null;},v->{onResolved.accept("purchase",id);refresh();});});}catch(Exception e){error(e);}}
 private void cancelPurchase(){try{UUID id=UUID.fromString(selected().get(0));Alert a=new Alert(Alert.AlertType.CONFIRMATION,"¿Cancelar esta solicitud? Una compra ya registrada no se cancelará.",ButtonType.OK,ButtonType.CANCEL);if(a.showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK)run(()->{purchaseRecovery.acknowledge(user,id,true);return null;},v->{onResolved.accept("purchase",id);refresh();});}catch(Exception e){error(e);}}
 public void resolvedElsewhere(String type,UUID id){if(type.equals("sale")&&id.equals(pendingKey)){pendingKey=null;pendingItems=null;cart.clear();refreshCart();status.setText("La venta pendiente fue resuelta; carrito vaciado.");}if(type.equals("purchase")&&pendingPurchase!=null&&id.equals(pendingPurchase.id())){pendingPurchase=null;purchaseItems.clear();refreshPurchaseDraft();status.setText("La compra pendiente fue resuelta; borrador vaciado.");}}
 private void purchaseAdd(){if(pendingPurchase!=null){error(new IllegalStateException("Resuelva primero la compra pendiente"));return;}run(()->ops.grid("stock"),grid->chooseRow("Seleccionar producto",grid.rows().stream().filter(row->row.size()>8&&Boolean.parseBoolean(row.get(8))).toList(),2,false,selected->{long product=Long.parseLong(selected.get(0));purchaseNames.put(product,selected.get(2));form("Lote · "+selected.get(2),new String[]{"Lote","Vence AAAA-MM-DD","Cantidad","Costo unitario"},new String[]{"","","1","0.00"},Set.of()).ifPresent(v->{try{var item=new PurchaseItem(product,v.get(0).trim(),LocalDate.parse(v.get(1)),Integer.parseInt(v.get(2)),new java.math.BigDecimal(v.get(3)));if(item.lot().isBlank()||!item.expiry().isAfter(LocalDate.now())||item.quantity()<=0||item.cost().signum()<0)throw new IllegalArgumentException("Revise lote, vencimiento, cantidad y costo");item.cost().setScale(2,java.math.RoundingMode.UNNECESSARY);purchaseItems.add(item);refreshPurchaseDraft();status.setText("Líneas de compra: "+purchaseItems.size());}catch(Exception e){error(e);}});}));}
 private void addPurchaseDraft(){purchaseDraft=new TableView<>();purchaseDraft.setPrefHeight(145);purchaseDraft.setPlaceholder(new Label("Agrega productos a la compra"));purchaseDraft.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_ALL_COLUMNS);purchaseColumn("Producto",p->purchaseNames.getOrDefault(p.productId(),"Producto "+p.productId()));purchaseColumn("Lote",PurchaseItem::lot);purchaseColumn("Vencimiento",p->p.expiry().toString());purchaseColumn("Cantidad",p->Integer.toString(p.quantity()));purchaseColumn("Costo unitario C$",p->p.cost().toPlainString());TableColumn<PurchaseItem,Void> remove=new TableColumn<>("Acción");remove.setCellFactory(col->new TableCell<>(){final Button b=new Button("Quitar");{b.setOnAction(e->{if(pendingPurchase!=null){error(new IllegalStateException("Resuelva primero la compra pendiente"));return;}purchaseItems.remove(getTableView().getItems().get(getIndex()));refreshPurchaseDraft();});}protected void updateItem(Void x,boolean empty){super.updateItem(x,empty);setGraphic(empty?null:b);}});purchaseDraft.getColumns().add(remove);getChildren().addAll(new Label("Borrador de compra"),purchaseDraft);refreshPurchaseDraft();}
 private void purchaseColumn(String title,java.util.function.Function<PurchaseItem,String> value){TableColumn<PurchaseItem,String> c=new TableColumn<>(title);c.setCellValueFactory(x->new javafx.beans.property.ReadOnlyStringWrapper(value.apply(x.getValue())));purchaseDraft.getColumns().add(c);}
 private void refreshPurchaseDraft(){if(purchaseDraft!=null)purchaseDraft.getItems().setAll(purchaseItems);}
 private void purchaseCommit(){if(pendingPurchase!=null){submitPurchase();return;}if(purchaseItems.isEmpty()){error(new IllegalArgumentException("La compra está vacía"));return;}run(()->ops.grid("suppliers"),grid->chooseRow("Seleccionar proveedor",grid.rows().stream().filter(row->Boolean.parseBoolean(row.get(3))).toList(),1,false,row->{pendingPurchase=new PurchaseRecovery.Pending(UUID.randomUUID(),Long.valueOf(row.get(0)),List.copyOf(purchaseItems));submitPurchase();}));}
 private void submitPurchase(){PurchaseRecovery.Pending request=pendingPurchase;run(()->{purchaseRecovery.save(user,request);return purchaseRecovery.resolve(user,request.id());},id->{info("Compra registrada #"+id);run(()->{purchaseRecovery.acknowledge(user,request.id(),false);return null;},v->{pendingPurchase=null;purchaseItems.clear();refreshPurchaseDraft();refresh();});});}
 private void display(ReportGrid g){currentGrid=g;table.getColumns().clear();for(int i=0;i<g.columns().size();i++){final int idx=i;TableColumn<List<String>,String> c=new TableColumn<>(label(g.columns().get(i)));c.setCellValueFactory(v->new javafx.beans.property.ReadOnlyStringWrapper(v.getValue().get(idx)));c.setMinWidth(100);c.setPrefWidth(155);table.getColumns().add(c);}filterRows();}
 private void filterRows(){if(currentGrid==null)return;String q=filter.getText().toLowerCase(Locale.ROOT).trim();table.getItems().setAll(currentGrid.rows().stream().filter(row->row.stream().anyMatch(value->value.toLowerCase(Locale.ROOT).contains(q))).toList());if(mode.equals("cart"))refreshCart();}
 private static String label(String key){return switch(key){case "id"->"ID";case "name"->"Nombre";case "code"->"Código";case "sale_price"->"Precio sin IVA";case "tax_rate"->"IVA";case "minimum_stock"->"Mínimo";case "total"->"Total";case "vendible"->"Vendible";case "active"->"Activo";case "blocked"->"Bloqueado";case "lot"->"Lote";case "expires_on"->"Vencimiento";case "quantity"->"Cantidad";case "created_at"->"Fecha";case "coalesce"->"Dato";case "status"->"Estado";case "tax"->"Impuesto";case "subtotal"->"Subtotal";case "role"->"Rol";case "username"->"Usuario";case "action"->"Acción";case "details"->"Detalle";case "kind"->"Tipo";case "key"->"Parámetro";case "value"->"Valor";default->key.replace('_',' ');};}
 private List<String> selected(){List<String> r=table.getSelectionModel().getSelectedItem();if(r==null)throw new IllegalArgumentException("Seleccione una fila");return r;}
 private Optional<List<String>> form(String title,String[] labels,String[] values,Set<Integer> secret){return FormControls.show(title,labels,values,secret);}
 private void contact(boolean edit){try{List<String> row=edit?selected():null;boolean supplier=mode.equals("suppliers");String[] labels=supplier?new String[]{"Nombre","Teléfono","Activo (true/false)"}:new String[]{"Nombre","Teléfono","RUC (opcional)"};String[] vals={edit?row.get(1):"",edit?row.get(2):"",supplier?(edit?row.get(3):"true"):(edit?row.get(3):"")};FormControls.save("Datos",labels,vals,Set.of(),Map.of(),v->{Long id=edit?Long.valueOf(row.get(0)):null;if(supplier)ops.contact(user,"supplier",id,v.get(0),v.get(1),bool(v.get(2)));else ops.customer(user,id,v.get(0),v.get(1),v.get(2));}).ifPresent(v->refresh());}catch(Exception e){error(e);}}
 private static boolean bool(String s){if(!s.equalsIgnoreCase("true")&&!s.equalsIgnoreCase("false"))throw new IllegalArgumentException("Use true o false");return Boolean.parseBoolean(s);}
 private void account(boolean edit){try{List<String> row=edit?selected():null;FormControls.save("Usuario",new String[]{"Usuario","Contraseña (vacía conserva)","Rol ADMIN o CASHIER","Activo true/false"},new String[]{edit?row.get(1):"","",edit?row.get(2):"CASHIER",edit?row.get(3):"true"},Set.of(1),Map.of(),v->ops.user(user,edit?Long.valueOf(row.get(0)):null,v.get(0),v.get(1),v.get(2),bool(v.get(3)))).ifPresent(v->refresh());}catch(Exception e){error(e);}}
 private void adjust(){try{long id=Long.parseLong(selected().get(0));FormControls.save("Ajustar lote",new String[]{"Variación (+/-)","Motivo"},new String[]{"",""},Set.of(),Map.of(),v->ops.adjust(user,id,Integer.parseInt(v.get(0)),v.get(1))).ifPresent(v->refresh());}catch(Exception e){error(e);}}
 private void block(){try{var row=selected();long id=Long.parseLong(row.get(0));boolean b=!bool(row.get(6));run(()->{ops.block(user,id,b);return null;},x->refresh());}catch(Exception ex){error(ex);}}
 private void receipt(){try{long id=Long.parseLong(selected().get(0));run(()->ops.receipt(id),OperationalPane::info);}catch(Exception ex){error(ex);}}
 private void printReceipt(){try{long id=Long.parseLong(selected().get(0));run(()->ops.receipt(id),text->{javafx.print.PrinterJob job=javafx.print.PrinterJob.createPrinterJob();if(job==null){error(new IllegalStateException("No hay impresora disponible"));return;}if(job.showPrintDialog(getScene().getWindow())){var layout=job.getJobSettings().getPageLayout();int width=Math.max(20,(int)(layout.getPrintableWidth()/6));int height=Math.max(5,(int)(layout.getPrintableHeight()/14)-2);List<String> lines=new ArrayList<>();for(String raw:text.split("\n",-1)){if(raw.isEmpty())lines.add("");else for(int i=0;i<raw.length();i+=width)lines.add(raw.substring(i,Math.min(i+width,raw.length())));}boolean ok=true;for(int i=0;i<lines.size()&&ok;i+=height){javafx.scene.text.Text page=new javafx.scene.text.Text(String.join("\n",lines.subList(i,Math.min(i+height,lines.size()))));page.setFont(javafx.scene.text.Font.font("Monospaced",9));ok=job.printPage(page);}if(ok)job.endJob();else{job.cancelJob();error(new IllegalStateException("No se pudo imprimir el comprobante"));}}});}catch(Exception ex){error(ex);}}
 private void voidSale(){try{long id=Long.parseLong(selected().get(0));FormControls.save("Anular venta "+id,new String[]{"Motivo"},new String[]{""},Set.of(),Map.of(),v->ops.voidSale(user,id,v.get(0))).ifPresent(v->refresh());}catch(Exception e){error(e);}}
 private void backup(){FileChooser executable=new FileChooser();executable.setTitle("Seleccione pg_dump de PostgreSQL");executable.getExtensionFilters().add(new FileChooser.ExtensionFilter("pg_dump", "pg_dump", "pg_dump.exe"));File pg=executable.showOpenDialog(getScene().getWindow());if(pg==null)return;FileChooser dest=new FileChooser();dest.setTitle("Guardar respaldo PostgreSQL");dest.setInitialFileName("sigf-respaldo-"+LocalDate.now()+".dump");dest.getExtensionFilters().add(new FileChooser.ExtensionFilter("Respaldo PostgreSQL","*.dump"));File file=dest.showSaveDialog(getScene().getWindow());if(file==null)return;run(()->{new BackupService(db).create(user,pg.toPath(),file.toPath());return null;},x->info("Respaldo creado. Guárdelo en un lugar protegido y compruebe su restauración."));}
 private void internalSeries(){form("Serie interna de prueba (sin valor fiscal)",new String[]{"Serie","Próximo número"},new String[]{"DEMO","1"},Set.of()).ifPresent(v->{try{long next=Long.parseLong(v.get(1));run(()->{ops.internalSeries(user,v.get(0),next);return null;},x->info("Serie interna actualizada. No constituye autorización fiscal."));}catch(Exception e){error(e);}});}
 private void setting(){try{var row=selected();FormControls.save("Modificar configuración",new String[]{"Valor"},new String[]{row.get(1)},Set.of(),Map.of(),v->ops.setting(user,row.get(0),v.get(0))).ifPresent(v->refresh());}catch(Exception e){error(e);}}
 private void clearPurchase(){if(pendingPurchase==null){purchaseItems.clear();refreshPurchaseDraft();status.setText("Compra vacía");return;}UUID id=pendingPurchase.id();run(()->{purchaseRecovery.cancelOrDiscard(user,id);return null;},v->{pendingPurchase=null;purchaseItems.clear();refreshPurchaseDraft();onResolved.accept("purchase",id);status.setText("Borrador de compra cancelado");});}
 private void clearCart(){if(pendingKey==null){cart.clear();refreshCart();status.setText("Carrito vacío");return;}UUID id=pendingKey;run(()->{recovery.cancelOrDiscard(user,id);return null;},v->{pendingKey=null;pendingItems=null;cart.clear();refreshCart();onResolved.accept("sale",id);status.setText("Carrito y solicitud cancelados");});}
 private void refreshCart(){if(cartView!=null)cartView.refresh();}
 private void cartAdd(){try{cartView.add(selected());}catch(Exception e){error(e);}}
 private void checkout(){if(pendingKey!=null){submitPending();return;}if(cart.isEmpty()){error(new IllegalArgumentException("Carrito vacío"));return;}List<CartItem> snapshot=List.copyOf(cart);run(()->ops.quoteDetailed(snapshot),detail->run(()->ops.grid("customers"),grid->{
  LinkedHashMap<String,Long> clients=new LinkedHashMap<>();clients.put("Consumidor final",null);for(var row:grid.rows())clients.put(row.get(0)+" · "+row.get(1),Long.valueOf(row.get(0)));
  Dialog<ButtonType> dialog=new Dialog<>();dialog.setTitle("Confirmar venta");dialog.setHeaderText("Revisa los datos antes de registrar la venta");ButtonType confirm=new ButtonType("Confirmar venta",ButtonBar.ButtonData.OK_DONE);dialog.getDialogPane().getButtonTypes().addAll(confirm,ButtonType.CANCEL);
  ComboBox<String> customer=SearchableChoices.create(clients.keySet(),"Consumidor final");customer.setId("saleCustomer");
  ComboBox<String> payment=new ComboBox<>();payment.getItems().addAll("Efectivo","Tarjeta","Transferencia");payment.setId("salePayment");payment.setValue("Efectivo");payment.setMaxWidth(Double.MAX_VALUE);
  Receipt quote=detail.totals();Label summary=new Label("Subtotal: C$ "+quote.subtotal()+"   ·   IVA: C$ "+quote.tax()+"   ·   Total: C$ "+quote.total());Label notice=new Label("Comprobante interno sin valor fiscal.");notice.getStyleClass().add("muted");VBox box=new VBox(10,summary,new Label("Cliente"),customer,new Label("Forma de pago"),payment,notice);box.setPadding(new Insets(15));dialog.getDialogPane().setContent(box);
  dialog.getDialogPane().lookupButton(confirm).addEventFilter(javafx.event.ActionEvent.ACTION,event->{String value=customer.getEditor().getText();if(!clients.containsKey(value)){event.consume();error(new IllegalArgumentException("Seleccione un cliente de la lista"));}});
  if(dialog.showAndWait().orElse(ButtonType.CANCEL)!=confirm)return;
  pendingClient=clients.get(customer.getEditor().getText());pendingMethod=switch(payment.getValue()){case "Tarjeta"->"CARD";case "Transferencia"->"TRANSFER";default->"CASH";};pendingKey=UUID.randomUUID();pendingItems=snapshot;pendingTotal=quote.total();SaleRecovery.Pending request=new SaleRecovery.Pending(pendingKey,pendingClient,pendingMethod,pendingTotal,pendingItems,detail.lines());run(()->{recovery.save(user,request);return null;},x->submitPending());
 }));}
 private void chooseRow(String title,List<List<String>> rows,int nameColumn,boolean optional,java.util.function.Consumer<List<String>> chosen){LinkedHashMap<String,List<String>> options=new LinkedHashMap<>();if(optional)options.put("Consumidor final",null);for(List<String> row:rows)options.put(row.get(0)+" · "+row.get(nameColumn),row);if(options.isEmpty()){error(new IllegalArgumentException("No hay registros disponibles"));return;}Dialog<ButtonType> dialog=new Dialog<>();dialog.setTitle(title);dialog.setHeaderText(title);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);ComboBox<String> combo=SearchableChoices.create(options.keySet(),options.keySet().iterator().next());combo.setPrefWidth(380);combo.setPromptText("Escriba para buscar");VBox box=new VBox(8,new Label("Escriba para filtrar y seleccione una opción"),combo);box.setPadding(new Insets(15));dialog.getDialogPane().setContent(box);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,e->{if(!options.containsKey(combo.getEditor().getText())){e.consume();error(new IllegalArgumentException("Seleccione una opción de la lista"));}});if(dialog.showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK)chosen.accept(options.get(combo.getEditor().getText()));}
 private void submitPending(){UUID id=pendingKey;run(()->recovery.resolve(user,id),receipt->{info("Comprobante de venta #"+receipt.id()+"\nSubtotal: "+receipt.subtotal()+"\nImpuesto: "+receipt.tax()+"\nTotal: "+receipt.total());run(()->{recovery.acknowledge(user,id,false);return null;},x->{pendingKey=null;pendingItems=null;cart.clear();refreshCart();refresh();});});}
 private void exportAll(){String q=query;LocalDate start=from.getValue(),end=to.getValue();FileChooser chooser=new FileChooser();chooser.setTitle("Guardar reporte completo");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("CSV","*.csv"));File file=chooser.showSaveDialog(getScene().getWindow());if(file==null)return;run(()->{ReportGrid grid=ops.report(q,start,end);try(var writer=Files.newBufferedWriter(file.toPath(),StandardCharsets.UTF_8)){writer.write(csv(grid.columns()));writer.newLine();for(var row:grid.rows()){writer.write(csv(row));writer.newLine();}}return null;},x->info("Reporte completo exportado."));}
 private void export(){FileChooser chooser=new FileChooser();chooser.setTitle("Guardar reporte CSV");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("CSV", "*.csv"));File f=chooser.showSaveDialog(getScene().getWindow());if(f==null)return;List<String> lines=new ArrayList<>();lines.add(csv(table.getColumns().stream().map(TableColumn::getText).toList()));for(var row:table.getItems())lines.add(csv(row));try{Files.write(f.toPath(),lines,StandardCharsets.UTF_8);info("Reporte exportado.");}catch(IOException e){error(e);}}
 private static String csv(List<String> values){return values.stream().map(v->"\""+((!v.isEmpty() && "=+-@".indexOf(v.charAt(0))>=0)?"'"+v:v).replace("\"","\"\"")+"\"").collect(java.util.stream.Collectors.joining(","));}
 private static void info(String s){new Alert(Alert.AlertType.INFORMATION,s,ButtonType.OK).showAndWait();}private static void error(Throwable e){new Alert(Alert.AlertType.ERROR,Objects.toString(e.getMessage(),"Error inesperado"),ButtonType.OK).showAndWait();}
}
